<?php
require_once __DIR__.'/../../includes/db.php';require_once __DIR__.'/../../includes/actas_service.php';validarPermiso('generar_actas');
if($_SERVER['REQUEST_METHOD']==='POST')try{cufaValidarToken();$id=cufaGenerarActa($pdo,cufaId($_POST,['asignacion_id']),(int)$_SESSION['user_id']);header('Location: '.cufaPanel('ver_acta',['id'=>$id]));exit;}catch(Throwable $e){cufaError($e);}
try{$f=cufaFiltros();$asignacion=cufaId($_GET,['asignacion_id']);}catch(Throwable $e){cufaError($e);return;}
$where=[];$args=[];foreach(['carrera_id'=>'g.carrera_id','grupo_id'=>'ad.grupo_id','periodo_id'=>'ad.periodo_id'] as $k=>$col)if($f[$k]){$where[]=$col.'=?';$args[]=$f[$k];}
$s=$pdo->prepare("SELECT ad.*,m.nombre materia,g.nombre grupo,p.nombre periodo,COALESCE(ac.generacion_habilitada,0) habilitada,(SELECT id FROM actas a WHERE a.asignacion_id=ad.id LIMIT 1) acta_id FROM asignaciones_docentes ad JOIN materias m ON m.id=ad.materia_id JOIN grupos g ON g.id=ad.grupo_id JOIN periodos p ON p.id=ad.periodo_id LEFT JOIN cufa_actas_control ac ON ac.periodo_id=ad.periodo_id".($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY p.id DESC,m.nombre');$s->execute($args);$asignaciones=$s->fetchAll();
?>
<h1 class="text-3xl font-bold mb-6">Generar actas</h1><div class="bg-white p-6 rounded-3xl mb-6 shadow"><p><strong>Generar</strong> congela las calificaciones aprobadas en un acta nueva. <strong>Habilitar actas</strong> controla si el periodo admite nuevas generaciones. <strong>Actas oficiales</strong> permite consultar, imprimir y descargar las ya existentes. No se sustituyen actas anteriores.</p></div>
<?php cufaFiltrosHtml($pdo,$f,'generar_actas'); ?>
<div class="bg-white rounded-3xl p-6 shadow"><?php foreach($asignaciones as $ad): ?><div class="border-b p-4"><strong><?= cufaEsc($ad['materia']) ?></strong> · <?= cufaEsc($ad['grupo'].' / '.$ad['periodo']) ?><p><?= $ad['habilitada']?'Generación habilitada':'Periodo cerrado para nuevas actas' ?></p>
<?php if($ad['acta_id']): ?><a class="text-purple-700 underline" href="<?= cufaEsc(cufaPanel('ver_acta',['id'=>$ad['acta_id']])) ?>">Consultar acta existente <?= (int)$ad['acta_id'] ?></a><?php else: ?><a class="text-purple-700 underline" href="<?= cufaEsc(cufaPanel('generar_actas',array_merge($f,['asignacion_id'=>$ad['id']]))) ?>">Ver requisitos y vista previa</a><?php endif; ?></div><?php endforeach; ?></div>
<?php if($asignacion): try{[$ad,$ids,$us,$filas]=cufaContexto($pdo,$asignacion);$listo=false;$motivo='';try{cufaCompleta($ids,$us,$filas);$listo=cufaEstado($filas)==='aprobado';cufaProtegerActa($pdo,$ad);$habilitado=$pdo->prepare('SELECT generacion_habilitada FROM cufa_actas_control WHERE periodo_id=?');$habilitado->execute([$ad['periodo_id']]);if((int)$habilitado->fetchColumn()!==1){$listo=false;$motivo='La generación de actas está cerrada para este periodo.';}if(!$listo && !$motivo)$motivo='Existen calificaciones sin aprobar.';}catch(Throwable $e){$listo=false;$motivo=$e->getMessage();} ?>
<div class="bg-white rounded-3xl p-6 shadow mt-6"><h2 class="text-2xl font-bold">Vista previa de notas vigentes</h2><p class="p-3"><?= $listo?'Notas completas y aprobadas.':cufaEsc($motivo) ?></p><table class="w-full"><tr class="bg-purple-200"><th>Alumno</th><th>Unidad</th><th>Final</th><th>Estado</th></tr><?php foreach($filas as $n): $a=cufaAlumno($pdo,(int)$n['alumno_id']); ?><tr class="border-t"><td class="p-3"><?= cufaEsc($a['nombre']) ?></td><td><?= (int)$n['unidad'] ?></td><td><?= cufaNumero($n['calificacion_final']) ?></td><td><?= cufaEsc($n['estado']) ?></td></tr><?php endforeach; ?></table>
<?php if($listo): ?><form method="POST" class="mt-6" onsubmit="return confirm('¿Generar un acta con copia fija de estas notas? No podrás reemplazarla desde este módulo.');"><input type="hidden" name="cufa_csrf" value="<?= cufaEsc(cufaToken()) ?>"><input type="hidden" name="asignacion_id" value="<?= $asignacion ?>"><button class="bg-purple-600 text-white p-4 rounded-xl">Generar acta</button></form><?php endif; ?></div>
<?php }catch(Throwable $e){cufaError($e);}endif; ?>
